python3 - <<'EOF'
p='src/board.ts'
s=open(p).read()
i=s.index('export function createBoard')
s=s[:i]+'''interface Column {
  name: string;
  index: number;
  wipLimit: number | undefined;
  cards: string[];
}

function assertRoom(column: Column): void {
  if (column.wipLimit !== undefined && column.cards.length >= column.wipLimit) {
    throw new BoardError("WIP_LIMIT", `Column ${column.name} is full`);
  }
}

export function createBoard(options: BoardOptions): Board {
  const columns = options.columns.map(
    ({ name, wipLimit }, index): Column => ({ name, index, wipLimit, cards: [] }),
  );
  const columnsByName = new Map(columns.map((column) => [column.name, column]));
  const location = new Map<string, Column>();
  const blocked = new Set<string>();
  let nextId = 1;

  function column(name: string): Column {
    const found = columnsByName.get(name);
    if (!found) throw new BoardError("UNKNOWN_COLUMN", `No column ${name}`);
    return found;
  }

  return {
    addCard(title) {
      if (title.trim() === "") throw new BoardError("EMPTY_TITLE", "Title must not be empty");
      const first = columns[0]!;
      assertRoom(first);
      const id = `C${nextId++}`;
      first.cards.push(id);
      location.set(id, first);
      return id;
    },
    move(cardId, toColumn) {
      const from = location.get(cardId);
      if (!from) throw new BoardError("UNKNOWN_CARD", `No card ${cardId}`);
      const to = column(toColumn);
      if (from === to) throw new BoardError("SAME_COLUMN", `${cardId} is already in ${toColumn}`);
      if (blocked.has(cardId)) throw new BoardError("BLOCKED", `${cardId} is blocked`);
      if (to.index > from.index + 1) {
        throw new BoardError("SKIP_NOT_ALLOWED", `${cardId} cannot skip columns`);
      }
      assertRoom(to);
      from.cards.splice(from.cards.indexOf(cardId), 1);
      to.cards.push(cardId);
      location.set(cardId, to);
    },
    block(cardId) {
      blocked.add(cardId);
    },
    unblock() {},
    cardsIn(name) {
      return [...column(name).cards];
    },
    cycleTime() {
      return null;
    },
  };
}
'''
open(p,'w').write(s)
EOF
